    20→
    21→function formatTime(date: Date): string {
    22→  return date.toLocaleTimeString("en-GB", { hour: "2-digit", minute: "2-digit" });
    23→}
    24→
    25→function timeAgo(date: Date): string {
    26→  const diff = Math.floor((Date.now() - date.getTime()) / 60000);
    27→  if (diff < 1) return "just now";
    28→  if (diff === 1) return "1 min ago";
    29→  if (diff < 60) return `${diff}m ago`;
    30→  const h = Math.floor(diff / 60);
    31→  return `${h}h ago`;
    32→}
    33→
    34→export default function LiveOverview() {
    35→  const level = getStatusLevel(stats.inStorage, stats.total);
    36→  const theme = statusTheme[level];
    37→  const pct = Math.round((stats.inStorage / stats.total) * 100);
    38→
    39→  return (
