    63→        <div
    64→          className="absolute top-0 right-0 w-40 h-40 opacity-[0.04]"
    65→          style={{
    66→            background: `radial-gradient(circle at top right, var(--gold), transparent 70%)`,
    67→          }}
    68→        />
    69→
    70→        <div className="flex flex-col sm:flex-row items-center gap-10">
    71→          {/* Big number */}
    72→          <div className="text-center sm:text-left">
    73→            <div className="flex items-baseline gap-2">
    74→              <span
